import{_ as o,C as n,o as d,c as s,a3 as a,E as e}from"./chunks/framework.CZBGEXos.js";const b=JSON.parse('{"title":"Початок роботи","description":"","frontmatter":{},"headers":[],"relativePath":"uk/getting-started.md","filePath":"uk/getting-started.md"}'),l={name:"uk/getting-started.md"};function i(h,t,p,c,m,g){const r=n("Screenshot");return d(),s("div",null,[t[0]||(t[0]=a('<h1 id="початок-роботи" tabindex="-1">Початок роботи <a class="header-anchor" href="#початок-роботи" aria-label="Permalink to &quot;Початок роботи&quot;">​</a></h1><p>Sentaro — це робочий простір для моніторингу криптовалют. Він читає загальнодоступні ринкові дані з Bybit, Binance, Gate.io, OKX та Hyperliquid (а також Kraken spot у <a href="/manual/uk/tools/ticks.html">Ticks</a>) і показує їх через набір спеціалізованих інструментів.</p><p>Користуватися ним можна двома способами, з тим самим акаунтом і тими самими інструментами:</p><table tabindex="0"><thead><tr><th></th><th>Веб-версія</th><th>Застосунок для Windows</th></tr></thead><tbody><tr><td>Де</td><td><a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> у будь-якому браузері</td><td>Завантажується з <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a></td></tr><tr><td>Системи</td><td>Windows, macOS, Linux</td><td>Лише Windows</td></tr><tr><td>Встановлення</td><td>Нічого встановлювати</td><td>Один інсталятор, оновлюється сам</td></tr><tr><td>Розкладка</td><td>Один інструмент на екрані, перемикання у верхній панелі</td><td>Кожен інструмент у власному вікні, розташування довільне</td></tr><tr><td><a href="/manual/uk/tools/terminal.html">Terminal</a></td><td>Недоступний</td><td>Доступний (експериментальний)</td></tr></tbody></table><p>Можна користуватися будь-яким або обома одночасно. Налаштування кожен зберігає окремо: веб-версія — у вашому браузері, застосунок для Windows — на комп&#39;ютері.</p><h2 id="акаунт" tabindex="-1">Акаунт <a class="header-anchor" href="#акаунт" aria-label="Permalink to &quot;Акаунт&quot;">​</a></h2><p>Sentaro використовує акаунт з email і паролем. При реєстрації на пошту надсилається 6-значний код підтвердження; введіть його, щоб підтвердити адресу, і після цього увійдіть. Також під час реєстрації потрібно прийняти Умови надання послуг.</p><p>Доступ безкоштовний для всіх, поки Sentaro у беті. Ваш статус — <strong>Beta test</strong>: у меню акаунта веб-версії (кругла кнопка вгорі праворуч) і у вкладці <strong>Home</strong> застосунку для Windows, разом з вашим email і встановленою версією. У застосунку для Windows email за замовчуванням прихований — натисніть іконку ока поруч, щоб його показати.</p><div class="tip custom-block"><p class="custom-block-title">Sentaro не має доступу до ваших біржових акаунтів</p><p>Усі інструменти моніторингу читають лише публічні ринкові дані. Sentaro не запитує API ключі бірж, не підключається до вашого акаунта і не може виставляти ордери на жодній з бірж, які він відстежує.</p><p>Єдиний виняток — експериментальний <a href="/manual/uk/tools/terminal.html">Terminal</a> у застосунку для Windows, окремий інструмент, який ви вмикаєте самі й підключаєте до Hyperliquid, Binance чи Bybit власними ключами. Без вашого свідомого налаштування він не робить нічого.</p></div><h2 id="веб-версія" tabindex="-1">Веб-версія <a class="header-anchor" href="#веб-версія" aria-label="Permalink to &quot;Веб-версія&quot;">​</a></h2>',10)),e(r,{src:"web-monitor",alt:"Веб-версія Sentaro з відкритим Monitor",caption:"Веб-версія — відкритий Monitor, під верхньою панеллю панель інструмента"}),t[1]||(t[1]=a('<p>Відкрийте <a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> і увійдіть.</p><h3 id="верхня-панель" tabindex="-1">Верхня панель <a class="header-anchor" href="#верхня-панель" aria-label="Permalink to &quot;Верхня панель&quot;">​</a></h3><ul><li><strong>Інструменти</strong> — Knives, Spreads, Analyzer, Monitor і Ticks. Натисніть, щоб перемкнутися. Веб-версія пам&#39;ятає останній відкритий інструмент.</li><li><strong>Пошук</strong> (<kbd>Ctrl</kbd> <kbd>K</kbd>) — відкрийте інструмент, його налаштування, загальні налаштування або цей довідник, набравши назву.</li><li><strong>Налаштування</strong> (іконка повзунків) — загальні налаштування: мова, акцентний колір, графіки, рисування та <a href="#спливаючі-вікна-нових-лістингів">спливаючі вікна нових лістингів</a>.</li><li><strong>Довідка</strong> — посилання на цей довідник.</li><li><strong>Акаунт</strong> — ваш email, статус бети та <strong>Sign out</strong>.</li></ul><h3 id="панель-інструмента" tabindex="-1">Панель інструмента <a class="header-anchor" href="#панель-інструмента" aria-label="Permalink to &quot;Панель інструмента&quot;">​</a></h3><p>Під верхньою панеллю кожен інструмент має власну панель. Чипи на ній — це <strong>швидкі фільтри</strong>: кожен показує налаштування, що діє (наприклад <code>Spread ≥ 1%</code> або <code>1m chart</code>), і відкриває невелике вікно, щоб змінити його на місці. Іконка праворуч відкриває всі налаштування інструмента в бічній панелі. Зміни застосовуються одразу.</p><h3 id="одна-вкладка-на-інструмент" tabindex="-1">Одна вкладка на інструмент <a class="header-anchor" href="#одна-вкладка-на-інструмент" aria-label="Permalink to &quot;Одна вкладка на інструмент&quot;">​</a></h3><p>Кожен інструмент отримує дані з серверів Sentaro, і в одного акаунта кожен інструмент може бути відкритий лише в одному місці одночасно. Якщо відкрити той самий інструмент в іншій вкладці браузера чи на іншому пристрої, перша покаже, що інструмент <em>відкрито в іншій вкладці або на іншому пристрої</em>, з кнопкою <strong>Use here</strong>, щоб повернути його.</p><h3 id="рисування-в-повноекранному-режимі" tabindex="-1">Рисування в повноекранному режимі <a class="header-anchor" href="#рисування-в-повноекранному-режимі" aria-label="Permalink to &quot;Рисування в повноекранному режимі&quot;">​</a></h3><p>Повноекранний графік у Knives, Monitor і Spreads має інструменти рисування: горизонтальний промінь, трендову лінію, прямокутник, олівець і олівець, що зникає, а також магніт. Клавіші ті самі, що й у застосунку для Windows (див. <a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a>). Рисунки зберігаються у вашому браузері для кожної монети й біржі та видні й на графіках карток цієї монети.</p><h2 id="застосунок-для-windows" tabindex="-1">Застосунок для Windows <a class="header-anchor" href="#застосунок-для-windows" aria-label="Permalink to &quot;Застосунок для Windows&quot;">​</a></h2><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><ol><li>Завантажте інсталятор кнопкою <strong>Download for Windows</strong> на <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a>.</li><li>Запустіть <code>.exe</code>.</li></ol><h4 id="попередження-smartscreen" tabindex="-1">Попередження SmartScreen <a class="header-anchor" href="#попередження-smartscreen" aria-label="Permalink to &quot;Попередження SmartScreen&quot;">​</a></h4><p>При першому завантаженні та запуску <strong>Windows Defender SmartScreen може попередити, що застосунок нерозпізнаний</strong>. Це очікувано і не є виявленням вірусу.</p><p>SmartScreen позначає будь-яку нову програму, яка ще не здобула репутацію в Microsoft — це лише означає, що файл завантажило замало людей, щоб довіряти йому автоматично. Через це проходить кожен новий незалежний застосунок, і попередження зникає само, коли кількість завантажень зростає.</p><p>Щоб його пройти:</p><ol><li>Натисніть <strong>Докладніше</strong> у вікні SmartScreen.</li><li>Натисніть <strong>Все одно запустити</strong>.</li><li>Це буває лише один раз — наступні запуски попередження не покажуть.</li></ol><h3 id="першии-запуск" tabindex="-1">Перший запуск <a class="header-anchor" href="#першии-запуск" aria-label="Permalink to &quot;Перший запуск&quot;">​</a></h3><p>Під час запуску Sentaro спершу перевіряє оновлення, а тоді просить увійти.</p><h3 id="робочии-простір" tabindex="-1">Робочий простір <a class="header-anchor" href="#робочии-простір" aria-label="Permalink to &quot;Робочий простір&quot;">​</a></h3>',20)),e(r,{src:"workspace",alt:"Робочий простір Sentaro з кількома відкритими вікнами інструментів",caption:"Робочий простір Sentaro — кілька вікон інструментів навколо головного вікна"}),t[2]||(t[2]=a('<p>Застосунок для Windows побудований навколо одного невеликого <strong>головного вікна</strong> плюс по вікну на кожен інструмент.</p><p>Ліворуч у головному вікні — вертикальна панель вкладок:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Що містить</th></tr></thead><tbody><tr><td>Home</td><td>Акаунт, мова, акцентний колір, налаштування графіків і рисування, спливаючі вікна нових лістингів</td></tr><tr><td>Knives</td><td>Налаштування <a href="/manual/uk/tools/knives.html">Knives</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Spreads</td><td>Налаштування <a href="/manual/uk/tools/spreads.html">Spreads</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Analyzer</td><td>Примітки <a href="/manual/uk/tools/analyzer.html">Analyzer</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Monitor</td><td>Налаштування <a href="/manual/uk/tools/monitor.html">Monitor</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Terminal</td><td>Налаштування <a href="/manual/uk/tools/terminal.html">Terminal</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Ticks</td><td>Налаштування <a href="/manual/uk/tools/ticks.html">Ticks</a> + кнопка <strong>Open Window</strong></td></tr></tbody></table><p>Усі інструменти працюють однаково: <strong>налаштування живуть у головному вікні, а сам інструмент відкривається окремим вікном.</strong> Натисніть <strong>Open Window</strong> у вкладці інструмента, щоб його запустити. Поки те вікно відкрите, кнопка показує <strong>Already Open</strong> і неактивна — кожен інструмент може мати лише одне вікно.</p><p>Оскільки кожен інструмент — незалежне вікно, ви можете вільно змінювати їхній розмір і розташування, будуючи потрібну розкладку, а головне вікно прибрати вбік.</p><p>Зміни налаштувань застосовуються наживо — відкрите вікно інструмента підхоплює їх без перезапуску. Налаштування записуються на диск автоматично.</p><h4 id="заголовок-вікна" tabindex="-1">Заголовок вікна <a class="header-anchor" href="#заголовок-вікна" aria-label="Permalink to &quot;Заголовок вікна&quot;">​</a></h4><p>Вікна інструментів мають власний заголовок Sentaro замість віндовського. Ліворуч у ньому <code>SENTARO</code> і назва активного інструмента, праворуч — згорнути / розгорнути / закрити. Щоб пересунути вікно, тягніть за будь-яке порожнє місце смуги.</p><h3 id="оновлення" tabindex="-1">Оновлення <a class="header-anchor" href="#оновлення" aria-label="Permalink to &quot;Оновлення&quot;">​</a></h3><p>Застосунок для Windows оновлюється сам. На кожному запуску він перевіряє наявність нової версії перед показом екрана входу; якщо вона є — завантажує, встановлює та перезапускається автоматично. На екрані завантаження при цьому видно <code>Checking for updates...</code>, а потім <code>Updating to v&lt;версія&gt;...</code>.</p><p>Робити нічого не потрібно. Встановлена версія показана у вкладці <strong>Home</strong> як <strong>App Version</strong>. Веб-версія завжди остання.</p><h2 id="спливаючі-вікна-нових-лістингів" tabindex="-1">Спливаючі вікна нових лістингів <a class="header-anchor" href="#спливаючі-вікна-нових-лістингів" aria-label="Permalink to &quot;Спливаючі вікна нових лістингів&quot;">​</a></h2><p>Коли монета починає торгуватися на одній з бірж, що відстежуються, з&#39;являється спливаюче вікно з біржею й символом, хоч би який інструмент був відкритий:</p><ul><li><strong>Веб-версія</strong> — у правому нижньому куті сторінки, поки вкладка Sentaro на екрані. Лістинг, що надійшов, поки вкладка у фоні, пізніше не показується.</li><li><strong>Застосунок для Windows</strong> — у правому нижньому куті екрана, поверх інших вікон, навіть коли Sentaro у фоні.</li></ul><p><strong>Copy</strong> копіює символ у буфер обміну. Вікно тримається 20 секунд і стільки, скільки на ньому курсор; <strong>×</strong> закриває його. Одночасно показується до чотирьох — п&#39;яте замінює найстаріше.</p><p>Про монету оголошується раз на біржу на добу, тож символ, який біржа ненадовго прибрала й повернула, не з&#39;явиться як новий. Вікна лише наживо: історії минулих лістингів немає.</p><p>Налаштування — у розділі <strong>New listings</strong> загальних налаштувань (веб) або вкладки <strong>Home</strong> (Windows):</p><ul><li><strong>Listing alert sound</strong> — звук разом із кожним вікном. Увімкнено за замовчуванням.</li><li><strong>Test pop-up</strong> — <strong>Send test</strong> показує тестове вікно для SOLUSDT на Bybit, надіслане через сервер, щоб перевірити, що вікна та звук працюють.</li></ul><h2 id="звуки" tabindex="-1">Звуки <a class="header-anchor" href="#звуки" aria-label="Permalink to &quot;Звуки&quot;">​</a></h2><p>Кожне сповіщення має свій звук, тож ви знаєте, що сталося, не дивлячись:</p><table tabindex="0"><thead><tr><th>Звук</th><th>Коли грає</th></tr></thead><tbody><tr><td>Rise</td><td><a href="/manual/uk/tools/knives.html">Knives</a>: монета перетнула ваш поріг у %</td></tr><tr><td>Chime</td><td>Knives: монета перетнула високий поріг</td></tr><tr><td>Duo pluck</td><td><a href="/manual/uk/tools/monitor.html">Monitor</a>: досягнуто поріг NATR або % зміни; <a href="/manual/uk/tools/spreads.html">Spreads</a>: відкрився новий спред</td></tr><tr><td>Blip</td><td><a href="/manual/uk/tools/ticks.html">Ticks</a>: велика угода</td></tr><tr><td>Fall</td><td>Ticks: ліквідація</td></tr><tr><td>Ding-dong</td><td><a href="#спливаючі-вікна-нових-лістингів">Спливаюче вікно нового лістингу</a></td></tr></tbody></table><p>Кожен вмикається чи вимикається в налаштуваннях свого інструмента. Браузер відтворює звук лише після того, як ви хоч раз клацнули на сторінці.</p><h2 id="мова" tabindex="-1">Мова <a class="header-anchor" href="#мова" aria-label="Permalink to &quot;Мова&quot;">​</a></h2><p>Інтерфейс Sentaro доступний англійською, українською та російською. Перемкнути можна в загальних налаштуваннях (веб) або у вкладці <strong>Home</strong> (Windows), вгорі. Це налаштування не пов&#39;язане з мовою, якою ви читаєте цей довідник.</p><h2 id="акцентнии-колір" tabindex="-1">Акцентний колір <a class="header-anchor" href="#акцентнии-колір" aria-label="Permalink to &quot;Акцентний колір&quot;">​</a></h2><p>У загальних налаштуваннях (веб) або у вкладці <strong>Home</strong> (Windows) ряд кольорових зразків задає акцентний колір для всього застосунку: Amber (за замовчуванням), Green, Blue, Purple, Red, Teal, Pink і White. Він діє в усіх інструментах.</p><p>Це окремо від кольорів свічок і метрик — про них див. <a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a>.</p><h2 id="повідомлення-про-помилки" tabindex="-1">Повідомлення про помилки <a class="header-anchor" href="#повідомлення-про-помилки" aria-label="Permalink to &quot;Повідомлення про помилки&quot;">​</a></h2><p>Коли щось іде не так — потік даних від&#39;єднався, вікно не відкрилося, збережені налаштування не завантажились — у правому нижньому куті з&#39;являється коротке повідомлення. Воно зникає саме за кілька секунд, або натисніть <strong>×</strong>, щоб закрити його. Те саме повідомлення показується не частіше ніж раз на 15 секунд, тож з&#39;єднання, що раз у раз перепідключається, не засипле екран.</p><p>Якщо помилка повертається знову й знову, напишіть про неї в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram-групу</a> з точним текстом.</p><h2 id="де-отримати-допомогу" tabindex="-1">Де отримати допомогу <a class="header-anchor" href="#де-отримати-допомогу" aria-label="Permalink to &quot;Де отримати допомогу&quot;">​</a></h2><p>Повідомлення про помилки та побажання — у <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">групу Telegram</a>. Це найшвидший спосіб отримати пряму відповідь.</p>',32))])}const k=o(l,[["render",i]]);export{b as __pageData,k as default};
